        else:
            if p.output_work_per_sm > 1.0e3:
                s = s + (f.parallel_reduction_traffic_fraction * (1.0 + f.split_k_partition_granularity)) * w[20]
                s = s + (f.parallel_reduction_traffic_fraction * np.log2(1.0 + f.mainloop_iteration_count)) * w[21]
